@@ -0,0 +1,72 @@
+package cli_test
+
+import (
+	"context"
+	"fmt"
+	"testing"
+
+	"github.com/urfave/cli/v3"
+)
+
+// Reproduction for urfave/cli#2176: a nil pointer dereference caused by
+// ensureHelp() mutating the package-level HelpFlag when Commands are run in
+// parallel.
+
+func runCliParallelRepro(args []string) {
+	cmd := &cli.Command{
+		Name:  "debug",
+		Usage: "make an explosive entrance",
+		Action: func(_ context.Context, cmd *cli.Command) error {
+			return nil
+		},
+	}
+
+	if err := cmd.Run(context.Background(), args); err != nil {
+		fmt.Printf("%s\n", err)
+	}
+}
+
+type parallelReproCase struct {
+	Name string
+	Args []string
+	Exit int
+}
+
+func runParallelReproCases(t *testing.T, tests []parallelReproCase) {
+	t.Parallel()
+
+	for _, tt := range tests {
+		t.Run(tt.Name, func(t *testing.T) {
+			t.Parallel()
+
+			defer func() {
+				if r := recover(); r != nil {
+					t.Errorf("unexpected panic - '%s' passing %s", r, tt.Args)
+				}
+			}()
+
+			runCliParallelRepro(tt.Args)
+		})
+	}
+}
+
+// Test_run is the reporter's test, verbatim apart from sharing the loop body.
+// Only two parallel subtests overlap per iteration, so on a 4-core machine it
+// did not fail in several million iterations.
+func Test_run(t *testing.T) {
+	runParallelReproCases(t, []parallelReproCase{
+		{Name: "hello_world", Exit: 0},
+		{Name: "hello_sunshine", Exit: 0},
+	})
+}
+
+// Test_run_many is the same test with 32 parallel subtests instead of 2 (a
+// more realistic test suite), which makes the overlap likely enough to fail
+// reliably.
+func Test_run_many(t *testing.T) {
+	var tests []parallelReproCase
+	for i := 0; i < 32; i++ {
+		tests = append(tests, parallelReproCase{Name: fmt.Sprintf("case_%d", i), Exit: 0})
+	}
+	runParallelReproCases(t, tests)
+}
